using System.Text;
using HakutaiKagami.Core.Messaging;
namespace HakutaiKagami.Core.Contracts;
public enum AdministrationAction { IssueTerms,AcceptTerms,DeclineTerms,SetPolicy }
public enum HousePolicy { Balanced,Build,Conserve,Military,Commerce }
public sealed record AdministrationInput(EntityId Id,AdministrationAction Action,EntityId Owner,EntityId Site,EntityId Person,EntityId? Reference=null,long AnnualCoins=300,WorksKind Priority=WorksKind.Agriculture,bool AvoidHarvest=true,HousePolicy Policy=HousePolicy.Balanced);
public sealed record AdministrationEvent(AdministrationInput Input,EntityId Actor,long At,long Revision);
public sealed record AdministrationPaper(string Id,string Type,EntityId Source,EntityId Sender,EntityId Recipient,EntityId Address,EntityId Site,long At,long Revision,long HouseRice,long HouseCash,EntityId[] Projects){[System.Text.Json.Serialization.JsonIgnore(Condition=System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull)]public DisasterObservation? Damage{get;init;}};
public sealed record AdministrationState(int Schema,string Policy,AdministrationEvent[] Events,AdministrationPaper[] Papers);
public static class StandingAdministration
{
 public const string Policy="accepted-standing-steward-annual-budget-known-policy-physical-monthly-report-v1",MessageKind="standing-administration";
 internal static AdministrationEvent[] Events(ContractWorld w)=>w.Administration?.Events??[];
 static void Need([System.Diagnostics.CodeAnalysis.DoesNotReturnIf(false)]bool ok,string why){if(!ok)throw new InvalidDataException(why);}
 static EntityId Id(string key)=>new("administration:"+ContractJson.Hash(Encoding.UTF8.GetBytes(key))[..28]);
 static bool Before(AdministrationEvent e,long at,long rev)=>e.At<at||e.At==at&&e.Revision<rev;
 static bool Head(ContractWorld w,EntityId actor,EntityId owner,EntityId site,long at,long rev)=>HouseSuccession.Head(w,owner,at,rev)==actor&&RegionalDomains.Owner(w,site)==owner&&RegionalDomains.Authority(w,actor,site,at,rev);
 static bool Office(ContractWorld w,EntityId actor,EntityId site,long at,long rev)=>w.Offices.Any(o=>o.Subject==actor&&o.Target==site&&(o.Kind is "house-steward" or "house-castellan" or "house-worksmagistrate" or "house-townmagistrate")&&o.From<=at&&(at<o.Until||at==o.Until&&rev<o.Revision));
 static DateOnly Date(ContractWorld w,long at)=>DateOnly.Parse(w.EpochDate).AddDays((int)(at/86400));
 public static bool OwnIdUsed(ContractWorld w,EntityId id)=>Events(w).Any(e=>e.Input.Id==id);
 static AdministrationEvent Source(ContractWorld w,EntityId id)=>Events(w).Single(e=>e.Input.Id==id);
 static string PaperId(EntityId source,EntityId recipient)=>"message:"+Id(source.Value+"/"+recipient.Value).Value.Replace(':','/');
 static bool Knows(ContractWorld w,EntityId source,EntityId recipient,long at)=>MessageFlow.LearnedAt(w.Messaging,PaperId(source,recipient),recipient.Value) is {} t&&t<=at;
 public static AdministrationEvent? Grant(ContractWorld w,EntityId actor,EntityId site,long at,long rev){var accept=Events(w).Where(e=>Before(e,at,rev)&&e.Actor==actor&&e.Input.Action==AdministrationAction.AcceptTerms).OrderBy(e=>e.Revision).LastOrDefault(e=>Source(w,e.Input.Reference!.Value).Input.Site==site);if(accept==null)return null;var t=Source(w,accept.Input.Reference!.Value);return Office(w,actor,site,at,rev)&&Head(w,t.Actor,t.Input.Owner,site,at,rev)?t:null;}
 public static HousePolicy KnownPolicy(ContractWorld w,EntityId person,EntityId owner,long at=long.MaxValue,long rev=long.MaxValue)=>Events(w).Where(e=>e.Input.Action==AdministrationAction.SetPolicy&&e.Input.Owner==owner&&Before(e,at,rev)&&(e.Actor==person||Knows(w,e.Input.Id,person,at))).OrderBy(e=>e.Revision).LastOrDefault()?.Input.Policy??HousePolicy.Balanced;
 internal static bool WorkAllowed(ContractWorld w,EntityId actor,EntityId site,long coins,long at,long rev){if(RegionalDomains.Head(w,site,at,rev)==actor)return true;var t=Grant(w,actor,site,at,rev);if(t==null)return false;var d=Date(w,at);return (!t.Input.AvoidHarvest||d.Month is not(9 or 10))&&PublicWorks.Orders(w).Where(q=>q.Actor==actor&&q.Input.Site==site&&q.Revision<rev&&Date(w,q.At).Year==d.Year).Sum(q=>q.Coins)+coins<=t.Input.AnnualCoins;}
 public static long Remaining(ContractWorld w,EntityId actor,EntityId site){var g=Grant(w,actor,site,w.ElapsedSeconds,w.CommitSequence+1);return g==null?0:Math.Max(0,g.Input.AnnualCoins-PublicWorks.Orders(w).Where(q=>q.Actor==actor&&q.Input.Site==site&&Date(w,q.At).Year==Date(w,w.ElapsedSeconds).Year).Sum(q=>q.Coins));}
 static MessageEnvelope Envelope(AdministrationPaper p)=>new(p.Id,p.Source.Value,MessageKind,p.Sender.Value,p.Recipient.Value,Encoding.UTF8.GetString(ContractJson.Write(p)),p.Site.Value,p.At);
 static void Send(ContractWorld w,AdministrationPaper p){w.Administration=w.Administration! with{Papers=[..w.Administration!.Papers,p]};MessageFlow.Send(w.Messaging,Envelope(p),p.At,1);w.SealedMessages=[..w.SealedMessages,new(p.Id)];}
 public static AdministrationPaper[] KnownPapers(ContractWorld w,EntityId actor)=>(w.Administration?.Papers??[]).Where(p=>p.Sender==actor||MessageFlow.Knows(w.Messaging,p.Id,actor.Value)).ToArray();
 public static AdministrationPaper[] Inbox(ContractWorld w,EntityId actor)=>(w.Administration?.Papers??[]).Where(p=>p.Recipient==actor&&w.Messaging.Attempts.Any(a=>a.MessageId==p.Id&&a.Status==AttemptStatus.Delivered&&a.ReceiverId==actor.Value)).ToArray();
 public static string? Address(ContractWorld w,MessageEnvelope m)=>w.Administration?.Papers.SingleOrDefault(p=>p.Id==m.Id) is {} p?NewGameWorld.Node(p.Address.Value):null;
 static void Check(ContractWorld w,AdministrationInput i,EntityId actor,long at,long rev){Need(NewGameWork.Enabled(w)&&Enum.IsDefined(i.Action)&&Enum.IsDefined(i.Priority)&&Enum.IsDefined(i.Policy)&&EntityId.IsValid(i.Id.Value),"行政の入力が不正です");
 if(i.Action==AdministrationAction.IssueTerms)Need(i.Reference==null&&i.AnnualCoins is >=50 and <=3000&&i.Priority is not(WorksKind.TradeShip or WorksKind.Warship)&&Head(w,actor,i.Owner,i.Site,at,rev)&&TransportWork.At(w,actor,i.Site,at,rev,true)&&Office(w,i.Person,i.Site,at,rev),"現地当主から、引受済みの奉行へ年度枠を示してください");
 else if(i.Action is AdministrationAction.AcceptTerms or AdministrationAction.DeclineTerms){Need(i.Reference!=null,"条件原本がありません");var t=Source(w,i.Reference.Value);Need(t.Input.Action==AdministrationAction.IssueTerms&&t.Input.Person==actor&&t.Input.Owner==i.Owner&&t.Input.Site==i.Site&&Knows(w,t.Input.Id,actor,at)&&Head(w,t.Actor,i.Owner,i.Site,at,rev)&&Office(w,actor,i.Site,at,rev)&&!Events(w).Any(e=>Before(e,at,rev)&&e.Input.Reference==t.Input.Id&&e.Input.Action is AdministrationAction.AcceptTerms or AdministrationAction.DeclineTerms),"受領した条件・有効な任命と本人の返答を確認してください");}
 else Need(i.Reference!=null&&Head(w,actor,i.Owner,i.Site,at,rev)&&TransportWork.At(w,actor,i.Site,at,rev,true)&&HouseholdCourt.Events(w).Any(e=>e.Input.Id==i.Reference&&e.Input.Action==CourtAction.HoldCouncil&&e.Actor==actor&&e.Input.Owner==i.Owner&&e.Place==i.Site&&e.At<=at&&at<=e.At+3600),"実際に開いた自家の評定で方針を決めてください");}
 public static void Execute(ContractWorld w,AdministrationInput i,EntityId actor){Check(w,i,actor,w.ElapsedSeconds,w.CommitSequence);w.Administration??=new(1,Policy,[],[]);w.Administration=w.Administration with{Events=[..Events(w),new(i,actor,w.ElapsedSeconds,w.CommitSequence)]};if(i.Action==AdministrationAction.IssueTerms){var address=w.NewGame!.Start.People.Single(p=>p.Id==i.Person.Value).Site;Send(w,new(PaperId(i.Id,i.Person),"terms",i.Id,actor,i.Person,new(address),i.Site,w.ElapsedSeconds,w.CommitSequence,0,0,[]));}
 if(i.Action==AdministrationAction.SetPolicy)foreach(var person in w.Memberships.Where(m=>m.Target==i.Owner&&m.From<=w.ElapsedSeconds&&w.ElapsedSeconds<m.Until).Select(m=>m.Subject).Where(p=>p!=actor).Distinct()){var address=w.NewGame!.Start.People.Single(p=>p.Id==person.Value).Site;Send(w,new(PaperId(i.Id,person),"policy",i.Id,actor,person,new(address),i.Site,w.ElapsedSeconds,w.CommitSequence,0,0,[]));}}
 internal static void Tick(ContractWorld w,bool advanced){if(w.Administration==null)return;foreach(var p in w.Administration.Papers.Where(p=>p.Recipient!=w.PlayerControl&&w.Messaging.Attempts.Any(a=>a.MessageId==p.Id&&a.ReceiverId==p.Recipient.Value&&a.Status==AttemptStatus.Delivered)).ToArray()){if(!MessageFlow.Knows(w.Messaging,p.Id,p.Recipient.Value))w.Messaging.Knowledge=[..w.Messaging.Knowledge,new(p.Id,p.Recipient.Value,w.ElapsedSeconds,p.Id)];if(p.Type=="terms"&&!Events(w).Any(e=>e.Input.Reference==p.Source&&e.Actor==p.Recipient&&e.Input.Action is AdministrationAction.AcceptTerms or AdministrationAction.DeclineTerms)){var t=Source(w,p.Source);TransactionalWorld.TryApply(w,c=>Execute(c,new(Id("accept/"+p.Source.Value),AdministrationAction.AcceptTerms,t.Input.Owner,t.Input.Site,t.Actor,t.Input.Id),p.Recipient));}}
 if(!advanced)return;var date=Date(w,w.ElapsedSeconds);foreach(var t in Events(w).Where(e=>e.Input.Action==AdministrationAction.AcceptTerms&&e.Actor!=w.PlayerControl).OrderBy(e=>e.Revision).Select(e=>Source(w,e.Input.Reference!.Value)).GroupBy(t=>(t.Input.Person,t.Input.Site)).Select(g=>g.Last()).ToArray()){var actor=t.Input.Person;var g=Grant(w,actor,t.Input.Site,w.ElapsedSeconds,w.CommitSequence+1);if(g==null||SocialWorld.Site(w,actor)!=t.Input.Site)continue;var policy=KnownPolicy(w,actor,t.Input.Owner);var priority=policy==HousePolicy.Commerce?WorksKind.Commerce:policy==HousePolicy.Military?WorksKind.Workshop:g.Input.Priority;
 if(!PublicWorks.MayOrder(w,actor,t.Input.Site,priority,w.ElapsedSeconds,w.CommitSequence+1))
     priority=HouseholdCourt.Specialist(w,actor,t.Input.Site,w.ElapsedSeconds,w.CommitSequence+1)==CourtRole.TownMagistrate?
         WorksKind.Commerce:WorksKind.Agriculture;
 if(policy!=HousePolicy.Conserve&&WorkAllowed(w,actor,t.Input.Site,50,w.ElapsedSeconds,w.CommitSequence+1)&&!PublicWorks.Orders(w).Any(q=>q.Input.Site==t.Input.Site&&q.Due>w.ElapsedSeconds))TransactionalWorld.TryApply(w,c=>PublicWorks.Execute(c,new(Id("work/"+actor.Value+"/"+w.ElapsedSeconds/86400),t.Input.Site,priority),actor));
 if(date.Day==1&&!w.Administration!.Papers.Any(p=>p.Type=="report"&&p.Sender==actor&&Date(w,p.At).Year==date.Year&&Date(w,p.At).Month==date.Month)){var account=CommunityEconomy.AccountAt(w,t.Input.Site,w.ElapsedSeconds,w.CommitSequence+1);var source=Id("report/"+actor.Value+"/"+date.ToString("yyyyMM"));var address=new EntityId(w.NewGame!.Start.People.Single(p=>p.Id==t.Actor.Value).Site);Send(w,new(PaperId(source,t.Actor),"report",g.Input.Id,actor,t.Actor,address,t.Input.Site,w.ElapsedSeconds,w.CommitSequence,account.HouseRice,RegionalDomains.Cash(w,t.Input.Site,w.ElapsedSeconds,w.CommitSequence+1),PublicWorks.Orders(w).Where(q=>q.Actor==actor&&q.Input.Site==t.Input.Site&&q.Revision<=w.CommitSequence).Select(q=>q.Input.Id).ToArray()){Damage=RegionalWeather.Observe(w,t.Input.Site,w.ElapsedSeconds,w.CommitSequence+1)});}}
 foreach(var f in HouseSuccession.Factions(w)){var owner=new EntityId(f.Id);var head=new EntityId(f.Head);var home=new EntityId(f.Home);if(SocialWorld.Site(w,head)!=home)continue;if(date.Day==1&&!HouseholdCourt.Events(w).Any(e=>e.Actor==head&&e.Input.Action==CourtAction.Convene&&Date(w,e.At).Year==date.Year&&Date(w,e.At).Month==date.Month)){var people=HouseholdCourt.Roster(w,head,owner).Where(p=>p!=head).ToArray();if(people.Length>0){var meetingId=Id("regular/"+owner.Value+"/"+date.ToString("yyyyMM"));if(TransactionalWorld.TryApply(w,c=>HouseholdCourt.Execute(c,new(meetingId,CourtAction.Convene,head,owner,home,When:w.ElapsedSeconds+3600){People=people},head))&&head!=w.PlayerControl)foreach(var invitation in HouseholdCourt.DocumentRows(w).Where(d=>d.Source.Input.Id==meetingId&&SocialWorld.Site(w,d.Recipient)==home).ToArray())TransactionalWorld.TryApply(w,c=>HouseholdCourt.Execute(c,new(Id("regular-invite/"+invitation.Id.Value),CourtAction.DeliverDocument,invitation.Recipient,owner,home,Reference:invitation.Id),head));}}
 if(head==w.PlayerControl)continue;var meeting=HouseholdCourt.Events(w).Where(e=>e.Actor==head&&e.Input.Action==CourtAction.HoldCouncil&&e.At<=w.ElapsedSeconds&&w.ElapsedSeconds<=e.At+3600).LastOrDefault();if(meeting!=null&&!Events(w).Any(e=>e.Input.Action==AdministrationAction.SetPolicy&&e.Input.Reference==meeting.Input.Id)){var a=CommunityEconomy.AccountAt(w,home,w.ElapsedSeconds,w.CommitSequence+1);var policy=a.Hunger>0||a.HouseRice<500?HousePolicy.Conserve:HousePolicy.Build;TransactionalWorld.TryApply(w,c=>Execute(c,new(Id("policy/"+meeting.Input.Id.Value),AdministrationAction.SetPolicy,owner,home,head,meeting.Input.Id,Policy:policy),head));}}
 }
 internal static long? NextBoundary(ContractWorld w,long target){if(w.Administration==null)return null;var d=Date(w,w.ElapsedSeconds);long day=(new DateOnly(d.Year,d.Month,1).AddMonths(1).DayNumber-DateOnly.Parse(w.EpochDate).DayNumber)*86400L;return day<=target?day:null;}
 public static void Validate(ContractWorld w,ContractWorld? prior){if(w.Administration==null){Need(prior?.Administration==null,"行政の原本が消えています");return;}Need(NewGameWork.Enabled(w)&&w.Administration.Schema==1&&w.Administration.Policy==Policy&&(Events(w).Length>0||LiveTerritory.Enabled(w)),"行政の保存形式が不正です");if(prior?.Administration!=null){Need(Events(w).Take(prior.Administration.Events.Length).SequenceEqual(prior.Administration.Events),"過去の行政を変えています");Need(ContractJson.CanonicalHash(w.Administration.Papers.Take(prior.Administration.Papers.Length).ToArray())==ContractJson.CanonicalHash(prior.Administration.Papers),"過去の報告を変えています");}long rev=0,at=0;var ids=new HashSet<EntityId>();foreach(var e in Events(w)){Need(e.Revision>=rev&&e.Revision<=w.CommitSequence&&e.At>=at&&e.At<=w.ElapsedSeconds&&ids.Add(e.Input.Id),"行政の時点が不正です");Check(w,e.Input,e.Actor,e.At,e.Revision);rev=e.Revision;at=e.At;}
 foreach(var p in w.Administration.Papers){Need(p.Damage==null||p.Type=="report"&&p.Damage==RegionalWeather.Observe(w,p.Site,p.At,p.Revision+1),"当時の災害観測と報告が違います");Need(p.At>=0&&p.At<=w.ElapsedSeconds&&p.Revision>0&&p.Revision<=w.CommitSequence&&w.Messaging.Messages.Count(m=>m.Id==p.Id&&m==Envelope(p))==1&&w.SealedMessages.Contains(new(p.Id)),"行政書状に観測原本がありません");var t=Source(w,p.Source);Need(p.Site==t.Input.Site&&p.Type is "terms" or "policy" or "report","行政の文書種別が不正です");if(p.Type is "terms" or "policy")Need(p.Id==PaperId(t.Input.Id,p.Recipient)&&p.Sender==t.Actor&&p.At==t.At&&p.Revision==t.Revision&&p.HouseRice==0&&p.HouseCash==0&&p.Projects.Length==0&&t.Input.Action==(p.Type=="terms"?AdministrationAction.IssueTerms:AdministrationAction.SetPolicy),"行政の条件・方針書が不正です");else Need(Grant(w,p.Sender,p.Site,p.At,p.Revision+1)?.Input.Id==p.Source&&TransportWork.At(w,p.Sender,p.Site,p.At,p.Revision,true)&&p.HouseRice==CommunityEconomy.AccountAt(w,p.Site,p.At,p.Revision+1).HouseRice&&p.HouseCash==RegionalDomains.Cash(w,p.Site,p.At,p.Revision+1)&&p.Projects.SequenceEqual(PublicWorks.Orders(w).Where(q=>q.Actor==p.Sender&&q.Input.Site==p.Site&&q.Revision<=p.Revision).Select(q=>q.Input.Id)),"当時に観測していない月報です");}Need(w.Messaging.Messages.Count(m=>m.Kind==MessageKind)==w.Administration.Papers.Length,"行政書状の孤立原本です");}
}
public sealed partial class WorldSession
{
 public CommandResult ManageAdministration(AdministrationInput i,long revision){lock(gate){var old=StandingAdministration.Events(state).SingleOrDefault(e=>e.Input.Id==i.Id);if(old!=null)return new(old.Input==i?ResultCode.AlreadyAccepted:ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"受付済みです");if(revision!=state.CommitSequence)return new(ResultCode.StateChanged,i.Id,state.CommitSequence,"表示を更新してください");if(NewGameWork.OwnIdUsed(state,i.Id)||state.Requests.Any(q=>q.Id==i.Id))return new(ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"使用済みの原本です");try{Change(w=>StandingAdministration.Execute(w,i,w.PlayerControl));return new(ResultCode.Accepted,i.Id,state.CommitSequence,"本人への条件・方針と到達を分けて記録しました");}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException or OverflowException){return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,e.Message);}}}
}
